{
    "title": "Manifest.json Schema",
    "$schema": "http://json-schema.org/draft-07/schema",
    "$id": "https://qooxdoo.org/schema/Manifest-1-0-0.json",
    "description": "qooxdoo's Manifest files serve to provide meta information for a library in a structured way. Their syntax is in JSON. They have a more informational part (keyed info), which is more interesting for human readers, a technical part (named provides) that is used in the processing of generator configurations, and a part named externalResources to include CSS and Javascript files.",
    "type": "object",
    "required": [
        "provides",
        "$schema"
    ],
    "additionalProperties": false,
    "properties": {
        "$schema": {
            "type": "string",
            "description": "the json schema of the version of Manifest.json",
            "enum": [
                "https://qooxdoo.org/schema/Manifest-1-0-0.json",
                "https://raw.githubusercontent.com/qooxdoo/qooxdoo-compiler/master/source/resource/qx/tool/schema/Manifest-1-0-0.json"
            ]
        },
        "info": {
            "type": "object",
            "additionalProperties": false,
            "description": "General Information about the project",
            "properties": {
                "name": {
                    "type": "string",
                    "description": "Name of the library"
                },
                "summary": {
                    "type": "string",
                    "description": "Short summary of its purpose"
                },
                "description": {
                    "type": "string",
                    "description": "Descriptive text"
                },
                "keywords": {
                    "type": "array",
                    "description": "Lost of keywords, tags.",
                    "_uniqueItems": true,
                    "items": {
                        "type": "string"
                    }
                },
                "homepage": {
                    "type": "string",
                    "description": "Homepage URL of the library."
                },
                "license": {
                    "type": "string",
                    "description": "License(s) of the library"
                },
                "authors": {
                    "description": "List of Authors",
                    "type": "array",
                    "items": {
                        "type": "object",
                        "required": [
                            "name",
                            "email"
                        ],
                        "additionalProperties": false,
                        "properties": {
                            "name": {
                                "type": "string",
                                "examples": [
                                    "First Author"
                                ]
                            },
                            "email": {
                                "type": "string",
                                "examples": [
                                    "first.author@site.domain"
                                ]
                            },
                            "githubUser": {
                                "type": "string",
                                "pattern": "[^\\s]+"
                            },
                            "gitlabUser": {
                                "type": "string",
                                "pattern": "[^\\s]+"
                            },
                            "facebookUser": {
                                "type": "string",
                                "pattern": "[^\\s]+"
                            },
                            "twitterHandle": {
                                "type": "string",
                                "pattern": "^@[^\\s]+"
                            }
                        }
                    }
                },
                "version": {
                    "type": "string",
                    "description": "a semver compatible version string",
                    "//pattern": "^(\\d|[1-9]\\d*)\\.(\\d|[1-9]\\d*)\\.(\\d|[1-9]\\d*)(?:-([-\\dA-Za-z]+(?:\\.[\\dA-Za-z-]+)*))?(?:\\+([-\\dA-Za-z]+(?:\\.[-\\d0-9A-Za-z]+)*))?$"
                },
                "qooxdoo-versions": {
                    "type": "array",
                    "description": "(deprecated) An array of qooxdoo versions that this library is compatible with. This property is deprecated and will be removed in version 7."
                },
                "sourceViewUri": {
                    "type": "string",
                    "description": "URL to view the library's class code online. This URL will be used in generated API documentation. It has a special syntax and allows for placeholders (e.g. for the class name and the source line number)."
                }
            }
        },
        "provides": {
            "required": [
                "namespace",
                "class"
            ],
            "additionalProperties": false,
            "type": "object",
            "properties": {
                "namespace": {
                    "type": "string",
                    "description": "Library namespace (i.e. the namespace elements all class names in this library are prefixed with, e.g. foo for a main application class with name foo.Application)."
                },
                "encoding": {
                    "type": "string",
                    "default": "utf-8",
                    "description": "File encoding of source code files"
                },
                "class": {
                    "type": "string",
                    "default": "source/class",
                    "description": "Path to the library's class code relative to the Manifest.json file, up to but not including the root namespace folder"
                },
                "resource": {
                    "type": "string",
                    "default": "source/resource",
                    "description": "Path to the library's resources relative to the Manifest.json file, up to but not including the root namespace folder"
                },
                "translation": {
                    "type": "string",
                    "default": "source/translation",
                    "description": "Path to the library's translation files relative to the Manifest.json file"
                },
                "webfonts": {
                    "type": "array",
                    "description": "A list of webfont definitions",
                    "items": {
                        "type": "object",
                        "required": [
                            "name",
                            "resources"
                        ],
                        "additionalProperties": false,
                        "properties": {
                            "name": {
                                "type": "string",
                                "description": "Font name"
                            },
                            "defaultSize": {
                                "type": "number",
                                "description": "Default font size"
                            },
                            "mapping": {
                                "type": "string",
                                "description": "Path to a json font map relative to the resource folder"
                            },
                            "comparisonString": {
                                "type": "string",
                                "description": "String to test of font is loaded."
                            },
                            "resources": {
                                "type": "array",
                                "minItems": 1,
                                "items": {
                                    "type": "string",
                                    "description": "Path to the webfont file relative to the resource folder"
                                }
                            }
                        }
                    }
                },
                "application": {
                    "type": "object"
                }
            }
        },
        "requires": {
            "description": "a list of of needed libraries and contribs. the keys `qooxdoo-sdk` and `qooxdoo-compiler` are also recognized to descript the respective versions of these components",
            "type": "object",
            "required": [
                "@qooxdoo/framework",
                "@qooxdoo/compiler"
            ],
            "patternProperties": {
                "^.*$": {
                    "description": "semver compatible range pattern",
                    "type": "string"
                }
            },
            "additionalProperties": false
        },
        "externalResources": {
            "type": "object",
            "description": "Static Javascript and CSS files that shall be always included without further processing by qooxdoo. All paths are relative to the resource folder stated in the 'provides' section.",
            "properties": {
                "css": {
                    "type": "array",
                    "_uniqueItems": true,
                    "items": {
                        "type": "string",
                        "pattern": "[.]s?css$"
                    }
                },
                "script": {
                    "type": "array",
                    "_uniqueItems": true,
                    "items": {
                        "type": "string",
                        "pattern": "[.]js$"
                    }
                }
            }
        },
        "setup": {
            "description": "Setup Section - used in Qooxdoo SDK Manifest.json ... do we need this still?",
            "type": "object"
        }
    }
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "id": "https://schema.getpostman.com/json/collection/v1.0.0/",
    "type": "object",
    "properties": {
        "id": {
            "type": "string",
            "description": "Every collection is identified by the unique value of this field. The value of this field is usually easiest to generate using a [UID](https://tools.ietf.org/html/rfc4122#section-4.4%29) generator function. If you already have a collection, it is recommended that you maintain the same id since changing the id usually implies that this is a different collection than it was originally."
        },
        "name": {
            "type": "string",
            "description": "A collection's friendly name is defined by this field. You would want to set this field to a value that would allow you to easily identify this collection among a bunch of other collections, as such outlining its usage or content."
        },
        "description": {
            "oneOf": [
                {
                    "type": "string"
                },
                {
                    "type": "null"
                }
            ],
            "description": "Provide a long description of this collection using this field. This field supports markdown syntax to better format the description."
        },
        "order": {
            "type": "array",
            "items": {
                "type": "string"
            },
            "_uniqueItems": true,
            "description": "The order array ensures that your requests and folders don't randomly get shuffled up. It holds a sequence of [UUIDs](https://en.wikipedia.org/wiki/Universally_unique_identifier) corresponding to folders and requests.\n *Note that if a folder ID or a request ID (if the request is not already part of a folder) is not included in the order array, the request or the folder will not show up in the collection.*"
        },
        "folders": {
            "type": "array",
            "items": {
                "title": "Folder",
                "description": "One of the primary goals of Postman is to organize the development of APIs. To this end, it is necessary to be able to group requests together. This can be achived using 'Folders'. A folder just is an ordered set of requests.",
                "type": "object",
                "properties": {
                    "id": {
                        "type": "string",
                        "description": "In order to be able to uniquely identify different folders within a collection, Postman assigns each folder a unique ID (a [UUID](https://en.wikipedia.org/wiki/Globally_unique_identifier)). This field contains that value."
                    },
                    "name": {
                        "type": "string",
                        "description": "A folder's friendly name is defined by this field. You would want to set this field to a value that would allow you to easily identify this folder."
                    },
                    "description": {
                        "type": "string",
                        "description": "Essays about the folder go into this field!"
                    },
                    "order": {
                        "type": "array",
                        "items": {
                            "type": "string"
                        },
                        "_uniqueItems": true,
                        "description": "Postman preserves the order of your requests within each folder. This field holds a sequence of [UUIDs](https://en.wikipedia.org/wiki/Globally_unique_identifier), where each ID corresponds to a particular Postman request."
                    },
                    "collection_id": {
                        "type": "string",
                        "description": "Postman folders are always a part of a collection. That collection's unique ID (which is a [UUID](https://en.wikipedia.org/wiki/Globally_unique_identifier)) is stored in this field."
                    }
                },
                "required": [
                    "id",
                    "name",
                    "description",
                    "order"
                ]
            },
            "description": "Folders are the way to go if you want to group your requests and to keep things organised. Folders can also be useful in sequentially requesting a part of the entire collection by using [Postman Collection Runner](https://www.getpostman.com/docs/jetpacks_running_collections) or [Newman](https://github.com/postmanlabs/newman) on a particular folder."
        },
        "timestamp": {
            "type": "number",
            "multipleOf": 1
        },
        "requests": {
            "type": "array",
            "description": "",
            "items": {
                "title": "Request",
                "description": "A request represents an HTTP request.",
                "type": "object",
                "properties": {
                    "folder": {
                        "oneOf": [
                            {
                                "type": "string"
                            },
                            {
                                "type": "null"
