            },
            "transactionType": {
                "$ref": "#/definitions/lisaTransactionTypeType"
            },
            "dateSubmitted": {
                "$ref": "#/definitions/ISO8601-Timestamp"
            },
            "amount": {
                "type": "number"
            },
            "financialPeriod": {
                "$ref": "#/definitions/financialPeriodType"
            },
            "chargeDueTo": {
                "type": "object",
