                        "$ref": "#/definitions/ISO8601-Date"
                    },
                    "_links": {
                        "type": "object"
                    }
                },
                "required": [
                    "LISAManagerReferenceNumber",
                    "accountID",
                    "transferDate"
                ]
            },
            "incurredCharge": {
                "type": "object",
                "properties": {
                    "chargeLISATransactionID": {
                        "$ref": "#/definitions/IDType"
                    },
                    "_links": {
                        "type": "object"
                    }
                },
                "required": [
                    "chargeLISATransactionID"
