        "IDType": {
            "type": "string",
            "pattern": "^\\d{10}$"
        },
        "LISAManagerReferenceNumberType": {
            "type": "string",
            "pattern": "^Z\\d{6}$"
        },
        "transactionTypeType": {
            "type": "string",
            "enum": [
                "bonus",
                "charge"
            ]
        },
        "lisaTransactionTypeType": {
            "type": "string",
            "enum": [
                "deposit",
                "withdrawal",
                "HTBtransfer",
                "LISAtransfer",
                "bonusClaim",
                "chargeMade"
            ]
        },
        "complianceReasonType": {
            "type": "string",
            "enum": [
                "house-purchase",
                "over-sixty",
                "chargeable",
                "terminal-illness",
                "death"
            ]
        },
        "chargeReasonCodeType": {
            "type": "string",
            "enum": [
                "over-lisa-limit",
                "outside-age-range",
                "chargeable-withdrawal"
            ]
        },
        "supersedeReasonCodeType": {
            "type": "string",
            "enum": [
                "error-correction",
                "TBD"
            ]
        }
    }
